```json
{
  "root_causes": [
    {
      "service": "shipping",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name csvc, c.span_name cname, round(c.duration/1e6,1) client_ms, s.service_name ssvc, s.span_name sname, round(s.duration/1e6,2) server_ms, round((epoch(s.time)-epoch(c.time))*1000,1) start_gap_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id WHERE c.service_name='shipping' AND c.span_name='POST quote' ORDER BY c.time LIMIT 8",
          "claim": "Shipping's POST quote client span takes about 675ms, but quote's server span starts about 675ms later and runs 0.3ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT src, service_name, span_name, attr_span_kind k, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50ms, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM (SELECT 'abn' src, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name IN ('shipping','quote') AND attr_span_kind IN ('Server','Client') GROUP BY 1,2,3,4 ORDER BY 2,3,1",
          "claim": "Shipping's /get-quote server and client spans rise from about 1.5ms to 675ms; quote's own server spans stay near 0.3ms."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "shipping",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT src, service_name, span_name, attr_span_kind k, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50ms, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM (SELECT 'abn' src, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='checkout' AND span_name IN ('oteldemo.CheckoutService/PlaceOrder','prepareOrderItemsAndShippingQuoteFromCart','HTTP POST') GROUP BY 1,2,3,4 ORDER BY 2,3,1",
          "claim": "Checkout's PlaceOrder and shipping-quote preparation rise from about 10-20ms to about 690ms, while its other calls stay flat."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT src, service_name, span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50ms, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM (SELECT 'abn' src, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='frontend' AND span_name='POST /api/checkout' GROUP BY 1,2,3 ORDER BY 1",
          "claim": "Frontend POST /api/checkout p50 rises from about 24ms to about 699ms, matching the slow checkout calls."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT src, service_name, span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50ms, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM (SELECT 'abn' src, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='frontend-proxy' AND span_name='ingress' GROUP BY 1,2,3 ORDER BY 1",
          "claim": "Frontend-proxy ingress p95 rises from about 21ms to about 119ms, carrying the slow checkout requests to users."
        }
      ]
    }
  ]
}
```

